def estimate(suffix,key):
    bits=n=hb=hn=0
    for k,b,w in [('layer',400,100),(key,320,20)]:
        if (k.endswith('lm_head') if suffix else k=='lm_head'): hb=b/w;hn=w
        else: bits+=b;n+=w
    return bits/n,hb,hn*hb+bits
for key in ['lm_head','language_model.lm_head']:
    print(key,estimate(False,key),estimate(True,key))
assert estimate(False,'lm_head')==estimate(True,'lm_head')
assert estimate(True,'language_model.lm_head')==(4,16,720)
